-- Roles and skills cell: the skill progress log (progress-entry), moved from the
-- solo-empire SQLite progress_log table on 2026-10-11. Do not edit once applied.

CREATE TABLE roles_skills.progress_log (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    skill_id                 bigint,
    activity_type            text NOT NULL DEFAULT 'other' CHECK (activity_type IN ('study', 'practice', 'project', 'teaching', 'review', 'other')),
    title                    text NOT NULL CHECK (length(title) <= 500 AND length(title) >= 1),
    description              text,
    hours_spent              double precision CHECK (hours_spent IS NULL OR (hours_spent >= 0)),
    progress_before          integer CHECK (progress_before IS NULL OR (progress_before >= 0 AND progress_before <= 100)),
    progress_after           integer CHECK (progress_after IS NULL OR (progress_after >= 0 AND progress_after <= 100)),
    what_learned             text,
    challenges               text,
    next_steps               text,
    evidence_url             text CHECK (evidence_url IS NULL OR (length(evidence_url) <= 2000)),
    logged_at                timestamptz,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    FOREIGN KEY (workspace_id, skill_id) REFERENCES roles_skills.skills (workspace_id, id)
);
CREATE UNIQUE INDEX progress_log_legacy ON roles_skills.progress_log (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX progress_log_activity_type ON roles_skills.progress_log (workspace_id, activity_type);
CREATE INDEX progress_log_skill_id ON roles_skills.progress_log (workspace_id, skill_id);

ALTER TABLE roles_skills.create_keys DROP CONSTRAINT create_keys_kind_check;
ALTER TABLE roles_skills.create_keys ADD CONSTRAINT create_keys_kind_check CHECK (kind IN ('personal-role', 'personal-role-context-link', 'personal-role-goal-link', 'personal-role-project-link', 'personal-role-task-link', 'role-goal-link', 'skill-category', 'skill', 'role-path-step', 'role-project-allocation', 'role-skill-link', 'progress-entry'));

ALTER TABLE roles_skills.progress_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE roles_skills.progress_log FORCE ROW LEVEL SECURITY;
CREATE POLICY workspace_isolation ON roles_skills.progress_log
    USING (workspace_id = roles_skills.current_workspace())
    WITH CHECK (workspace_id = roles_skills.current_workspace());

GRANT SELECT, INSERT, UPDATE, DELETE ON roles_skills.progress_log TO roles_skills_api;
GRANT USAGE ON SEQUENCE roles_skills.progress_log_id_seq TO roles_skills_api;
